/// <summary>
/// Intialize rebate transaction gets the source item sales tax group
/// </summary>
/// <param name = "_rebateTrans">TAMRebateTrans buffer</param>
/// <param name = "_rebateJournalTrans">TAMRebateJournalTrans buffer</param>
/// <param name = "_rebateDatePeriod">RebateDatePeriod given as part fo rebate transaction</param>
/// <returns></returns>
protected boolean inititalizeRebateTransaction(TAMRebateTrans _rebateTrans, TAMRebateJournalTrans _rebateJournalTrans, TAMRebateDatePeriod _rebateDatePeriod)
{
    boolean ret = next inititalizeRebateTransaction(_rebateTrans, _rebateJournalTrans, _rebateDatePeriod);

    if (_rebateJournalTrans as TAMRebateJournalTransSalesOrder) //salesorder
    {
        SalesLine salesLine;

        select firstonly salesLine
            where salesLine.DataAreaId == _rebateTrans.RefCompanyId
            && salesLine.TableId == _rebateTrans.RefTableId
            && salesLine.RecId == _rebateTrans.RefRecId;

        _rebateTrans.METTaxItemGroup = salesLine.TaxItemGroup;
    }
    else 
    {
        if (rebateTable)
        {
            //as implementation is internal hence can`t check the object as above, its a purchase order
            if (rebateTable.SourceType == TAMRebateSourceType::Ordered && rebateTable.ModuleInventCustVend == ModuleInventCustVend::Vend)
            {
                PurchLine purchLine;

                select firstonly purchLine
                    where purchLine.DataAreaId == _rebateTrans.RefCompanyId
                    && purchLine.TableId == _rebateTrans.RefTableId
                    && purchLine.RecId == _rebateTrans.RefRecId;

                _rebateTrans.METTaxItemGroup = purchLine.TaxItemGroup;
            }
            //as implementation is internal hence can`t check the objact as above, its a FreeTextInvoice
            else if (rebateTable.SourceType == TAMRebateSourceType::Invoice && rebateTable.ModuleInventCustVend == ModuleInventCustVend::Cust)
            {
                CustInvoiceTrans custInvoiceTrans;

                select firstonly custInvoiceTrans
                    where custInvoiceTrans.DataAreaId == _rebateTrans.RefCompanyId
                    && custInvoiceTrans.TableId == _rebateTrans.RefTableId
                    && custInvoiceTrans.RecId == _rebateTrans.RefRecId;

                _rebateTrans.METTaxItemGroup = custInvoiceTrans.TaxItemGroup;
            }
        }
    }

    return ret;
}
